//go:build rp2350

// RP2350 backend: a PIO state machine clocks the encoded word stream onto GP0..GP13 while a
// DMA channel feeds it. The whole refresh waveform — every pixel, clock edge, latch and OE
// dwell — is generated by PIO+DMA with no CPU involvement. The CPU only re-arms the DMA once
// per completed frame (a few instructions in the completion IRQ), which is also where the
// tear-free double-buffer swap happens.
//
// PIO RESOURCE ALLOCATION. The state machine and instruction-memory slot are claimed through
// tinygo-org/pio (rp2-pio) — ClaimStateMachine + AddProgram — rather than hardcoded, so this
// driver shares PIO0 cleanly with other users of the same library (notably the cyw43439 WiFi
// bus, which claims its own SM on PIO0). Everything else (the SM register config, the count-
// loop program, the DMA) is still driven directly, since the library's config helpers don't
// express the autopull-threshold-32 + custom-wrap + OSR-drain setup this program needs.
//
// COEXISTENCE WITH WiFi: the cyw43439 bus claims a PIO0 state machine (via the same library,
// hence ClaimStateMachine below) and a DMA channel low-first via piolib's arbiter, and it
// drives that channel by polling (no DMA IRQ). This driver therefore takes a HIGH DMA channel
// (dmaChan) on DMA IRQ line 1 — disjoint from the wireless on both axes — so the pio display
// and WiFi share PIO0 + DMA cleanly (the 8-bit pio WiFi clock).
//
// Pin map (consecutive GPIOs, the Interstate 75 W wiring): GP0-5 R1 G1 B1 R2 G2 B2,
// GP6-10 ADDR A-E, GP11 CLK, GP12 LAT, GP13 OE.
package hub75

import (
	"device/rp"
	"machine"
	"runtime/interrupt"
	"runtime/volatile"
	"unsafe"

	rppio "github.com/tinygo-org/pio/rp2-pio"
)

// Pin bit positions within a word's low 14 bits, matching the Interstate 75 W wiring
// (GP0..GP13). The six RGB data lines are the low bits so a plane packs into bits 0-5.
const (
	bCLK = 1 << 11 // GP11
	bLAT = 1 << 12 // GP12
	bOE  = 1 << 13 // GP13 (active low: bit SET = output blanked)
)

// Word layout: the low 14 bits drive the pins; the high 18 are the PIO dwell count (how
// many extra cycles to hold this pin state). Shift/latch words use count 0; a hold word
// carries the BCM dwell.
const (
	countShift = 14
	maxCount   = (1 << 18) - 1

	// holdOverhead is the fixed PIO cycles a hold word costs beyond its count: out pins,
	// out x, and the loop's final fall-through. A hold word displays count+holdOverhead
	// cycles, so to display L cycles its count is L-holdOverhead.
	holdOverhead = 3

	// shiftWordCycles is the cycles a count-0 word costs (out pins + out x + fall-through):
	// the unit the blanked shift/latch beats are measured in for the duty calculation.
	shiftWordCycles = 3
)

// driverName is this build's engine name, exposed via hub75.DriverName.
const driverName = "pio"

// engine is pio's word-stream backend: a PIO state machine clocks the encoded stream while a
// DMA channel feeds it. It owns its configuration and the stream buffers; Device hands it the
// pixels to encode each present. Only one may run per program (one PIO state machine / one DMA
// chain / one output port).
type engine struct {
	// Configuration, derived from Config in start (the engine's own copy of what it needs to
	// encode — Device does not hold these).
	width, scanRows, planes int
	gamma                   [256]uint8 // gamma-2.6 curve scaled to planes bits
	brightness              uint8
	holdScale               uint32 // the lit holds' share of full at this brightness, in 1/65536ths (see holdScale)
	baseHold                int    // plane-0 BCM dwell in PIO cycles; plane k dwells baseHold<<k

	// Stream geometry. Every (row, plane) segment is the same length: 2*width shift words
	// (two per column for the clock edge) + 3 latch words + 1 count-encoded hold word.
	segWords  int
	rowWords  int
	streamLen int

	// Two word streams (double-buffered). The hardware refreshes from bufs[front]; present
	// encodes bufs[back], makes it live at a frame boundary, and flips the roles.
	bufs         [2][]uint32
	front, back  int
	doubleBuffer bool
}

// start derives the engine config from cfg, sizes and allocates the stream buffer(s), encodes
// the initial (black) pix, and claims the PIO/DMA. After it returns the panel refreshes with
// no CPU. Returns ErrTooBig if the buffers exceed the RAM budget, or ErrConfigured if the
// singleton engine is already claimed.
func (e *engine) start(cfg Config, pix []rgb) error {
	if started {
		return ErrConfigured
	}
	e.width = cfg.Width
	e.scanRows = cfg.Height / 2
	e.planes = cfg.ColorDepth
	e.gamma = scaleGamma(cfg.ColorDepth)
	e.brightness = resolveBrightness(cfg.Brightness)
	e.holdScale = holdScale(e.brightness, holdDutyRatio)
	e.baseHold = autoBaseHold(e.width, e.planes)
	e.doubleBuffer = cfg.DoubleBuffer

	e.segWords = 2*e.width + 4
	e.rowWords = e.planes * e.segWords
	e.streamLen = e.scanRows * e.rowWords

	bufBytes := e.streamLen * 4
	if e.doubleBuffer {
		bufBytes *= 2
	}
	if bufBytes > maxBufferBytes {
		return ErrTooBig
	}

	e.bufs[0] = make([]uint32, e.streamLen)
	e.encode(pix, e.bufs[0]) // black, with valid control bits
	if e.doubleBuffer {
		e.bufs[1] = make([]uint32, e.streamLen)
		e.encode(pix, e.bufs[1])
		e.front, e.back = 0, 1
	}
	// Single-buffer leaves front == back == 0: present rebuilds the live stream in place.

	live, want = 0, 0
	streamWords = uint32(e.streamLen)
	bufBase[0] = ptr(unsafe.Pointer(&e.bufs[0][0]))
	if e.doubleBuffer {
		bufBase[1] = ptr(unsafe.Pointer(&e.bufs[1][0]))
	} else {
		bufBase[1] = bufBase[0]
	}

	configurePins()
	if err := configurePIO(); err != nil {
		return err
	}
	configureDMA()
	started = true
	return nil
}

// present rebuilds the back stream from pix (gamma applied here), makes it live at the next
// frame boundary, and waits (bounded) for the swap, flipping the roles. Single-buffer rebuilds
// the live stream in place and returns immediately.
func (e *engine) present(pix []rgb) error {
	e.encode(pix, e.bufs[e.back])
	if !e.doubleBuffer {
		return nil
	}
	e.swap(e.back)
	if err := waitSwap(e.swapDone); err != nil {
		return err
	}
	e.front, e.back = e.back, e.front
	return nil
}

// setBrightness stores the new brightness: it scales each plane's OE-low dwell, but that dwell
// is the hold word's count, so the change takes effect on the next present (which re-encodes).
func (e *engine) setBrightness(b uint8) {
	if b == e.brightness {
		return // stress re-asserts its level every frame; skip recomputing the curve
	}
	e.brightness = b
	e.holdScale = holdScale(b, holdDutyRatio)
}

// swap asks the ISR to adopt buffer `to` at the next frame boundary.
func (e *engine) swap(to int) { want = to }

// swapDone reports whether the ISR has adopted the requested buffer.
func (e *engine) swapDone() bool { return live == want }

// encode writes the whole frame into buf. For each (row, plane) segment it shifts that
// plane's column data in blanked (OE high, CLK low then high per column), latches it, then
// emits one OE-low hold word whose count is the plane's BCM dwell (baseHold<<k) scaled for the
// brightness (holdScale: chosen so the light, not just the hold, follows the setting). The top half (grid row r) drives bits 0-2, the bottom half (r+scanRows) bits
// 3-5; the row address sits in bits 6-10 of the whole segment, changing only while blanked.
func (e *engine) encode(pix []rgb, buf []uint32) {
	scale := int64(e.holdScale)
	for r := 0; r < e.scanRows; r++ {
		addr := addrBits(r)
		for k := 0; k < e.planes; k++ {
			i := r*e.rowWords + k*e.segWords

			// Shift this plane's columns in, blanked; the panel samples on CLK's rise.
			for col := 0; col < e.width; col++ {
				base := e.planeBits(pix, r, k, col) | addr | bOE
				buf[i] = base
				buf[i+1] = base | bCLK
				i += 2
			}

			// Latch (still blanked): LAT high then low.
			buf[i] = addr | bOE
			buf[i+1] = addr | bOE | bLAT
			buf[i+2] = addr | bOE
			i += 3

			// Display: one OE-low word held for the plane's brightness-scaled dwell.
			lit := int(int64(e.baseHold<<uint(k)) * scale >> 16)
			c := lit - holdOverhead
			if c < 0 {
				c = 0
			}
			if c > maxCount {
				c = maxCount
			}
			buf[i] = addr | uint32(c)<<countShift
		}
	}
}

// planeBits packs bit `k` of each gamma-corrected channel at (row, col) into a word's low
// bits: top half (grid row r) on bits 0-2, bottom half (row r+scanRows) on bits 3-5.
func (e *engine) planeBits(pix []rgb, r, k, col int) uint32 {
	tp := pix[r*e.width+col]
	bp := pix[(r+e.scanRows)*e.width+col]
	ku := uint(k)
	return uint32((e.gamma[tp.R]>>ku)&1)<<0 |
		uint32((e.gamma[tp.G]>>ku)&1)<<1 |
		uint32((e.gamma[tp.B]>>ku)&1)<<2 |
		uint32((e.gamma[bp.R]>>ku)&1)<<3 |
		uint32((e.gamma[bp.G]>>ku)&1)<<4 |
		uint32((e.gamma[bp.B]>>ku)&1)<<5
}

// ----------------------------------------------------------------------------
// SCANOUT HARDWARE (PIO + DMA bring-up)
// ----------------------------------------------------------------------------
// The engine is a hardware SINGLETON — one PIO state machine, one DMA channel, one output
// port — so its running state is package-level rather than engine fields: the completion ISR
// (dmaISR, which can't be a method) shares the swap state (live/want) and the re-arm
// parameters (bufBase/streamWords/dmaCtrl), and the `started` guard rejects a second start
// with ErrConfigured. Per-frame pixel state lives on the Device's grid.

// maxBufferBytes caps the total stream buffer(s) so an over-deep config fails with
// ErrTooBig instead of OOM-ing to a blank panel. The RP2350 has 520 KB SRAM; this
// leaves headroom for the stack, runtime, and the app's own grid.
const maxBufferBytes = 384 * 1024

const (
	hubPinBase  = 0  // GP0: first HUB75 signal
	hubPinCount = 14 // GP0..GP13
	beatDiv     = 2  // PIO clock = 150 MHz / 2 = 75 MHz; a count-0 word is 3 cycles, so the
	//                  shift runs 25 MHz, the panel clock (2 words/pixel) 12.5 MHz. Hardware
	//                  refresh then depends on holdDutyRatio (~750 Hz at ratio 1, depth 8,
	//                  64×32). The panel tested clean up to 25 MHz (beatDiv 1); 12.5 MHz
	//                  keeps 2x margin with no visible cost (refresh is already flicker-free).

	// PIO program (hand-assembled). Each word is [count:18|pins:14]:
	//   out pins, 14    drive GP0..GP13 from the low 14 bits
	//   out x, 18       load the dwell count from the high 18 bits
	//   jmp x-- delay   hold this pin state `count` cycles (delay = the jmp itself)
	// AddProgram relocates the jmp target; EXECCTRL wraps the last instruction to the first.
	insOutPins14  = 0x600E
	insOutX18     = 0x6032
	insJmpXDecDly = 0x0042 // jmp x-- to program-relative addr 2 (relocated on load)

	// Pindir init (forced via the SM's INSTR while stopped): OSR := all ones, set 14 pins to
	// outputs, then discard the remaining 18 bits so the OSR is empty (shift count 32) and
	// the SM's first real `out pins` autopulls a fresh word from the FIFO.
	insMovOsrInvNul = 0xA0EB // mov osr, ~null
	insOutPindirs14 = 0x608E // out pindirs, 14
	insOutNull18    = 0x6072 // out null, 18
)

// program is the 3-instruction refresh loop, loaded via AddProgram (relocatable). Built from
// the ins* opcodes in the const block above.
var program = []uint16{insOutPins14, insOutX18, insJmpXDecDly}

var (
	started     bool
	live, want  int
	bufBase     [2]uint32 // word address of each stream buffer
	streamWords uint32
	dmaCtrl     uint32             // the data channel's CTRL_TRIG value, reused to re-arm in the ISR
	pioSM       rppio.StateMachine // the claimed state machine (for its FIFO + DREQ)
)

// dmaChan is the DMA channel this driver uses — deliberately high so the cyw43439 WiFi bus
// (which claims channels low-first) never reaches it.
const dmaChan = 11

// dmaChannelHW is one DMA channel's register block (0x40 stride): the four trigger registers
// plus the alias registers padding to the next channel. device/rp exposes them as flat
// CHn_* fields; this lets us address a chosen channel by index instead.
type dmaChannelHW struct {
	READ_ADDR   volatile.Register32
	WRITE_ADDR  volatile.Register32
	TRANS_COUNT volatile.Register32
	CTRL_TRIG   volatile.Register32
	_           [12]volatile.Register32 // aliases, to the next channel at +0x40
}

var dmaCh = (*dmaChannelHW)(unsafe.Pointer(uintptr(unsafe.Pointer(rp.DMA)) + uintptr(dmaChan)*0x40))

func ptr(p unsafe.Pointer) uint32 { return uint32(uintptr(p)) }

// configurePins hands GP0..GP13 to the PIO. PinMode() returns the right FUNCSEL for the
// claimed PIO block; machine's Configure does the RP2350 pad setup (clears isolation,
// enables the output driver).
func configurePins() {
	fn := rppio.PIO0.PinMode()
	for p := hubPinBase; p < hubPinBase+hubPinCount; p++ {
		machine.Pin(p).Configure(machine.PinConfig{Mode: fn})
	}
}

// configurePIO claims a PIO0 state machine and an instruction-memory slot via rp2-pio, then
// configures that SM's registers directly for the count-loop program and starts it. The SM
// stalls on the empty FIFO until configureDMA starts feeding it.
func configurePIO() error {
	sm, err := rppio.PIO0.ClaimStateMachine()
	if err != nil {
		return err
	}
	offset, err := rppio.PIO0.AddProgram(program, -1) // -1: relocatable, allocator picks the slot
	if err != nil {
		return err
	}
	pioSM = sm

	sm.SetEnabled(false)
	h := sm.HW() // the claimed SM's CLKDIV/EXECCTRL/SHIFTCTRL/PINCTRL/INSTR registers

	// SM clock: 150 MHz / beatDiv.
	h.CLKDIV.Set(uint32(beatDiv) << rp.PIO0_SM0_CLKDIV_INT_Pos)

	// Wrap the last program instruction back to the first (relocated by offset).
	h.EXECCTRL.Set(
		(uint32(offset+2) << rp.PIO0_SM0_EXECCTRL_WRAP_TOP_Pos) |
			(uint32(offset) << rp.PIO0_SM0_EXECCTRL_WRAP_BOTTOM_Pos))

	// Autopull on, threshold 32 (field 0 = 32: refill once a whole word is consumed by
	// out pins,14 + out x,18), shift right so word bit 0 maps to GP0.
	h.SHIFTCTRL.Set(
		(1 << rp.PIO0_SM0_SHIFTCTRL_AUTOPULL_Pos) |
			(0 << rp.PIO0_SM0_SHIFTCTRL_PULL_THRESH_Pos) |
			(1 << rp.PIO0_SM0_SHIFTCTRL_OUT_SHIFTDIR_Pos))

	// OUT maps to GP0..GP13.
	h.PINCTRL.Set(
		(hubPinBase << rp.PIO0_SM0_PINCTRL_OUT_BASE_Pos) |
			(hubPinCount << rp.PIO0_SM0_PINCTRL_OUT_COUNT_Pos))

	// Set the 14 pins to outputs and drain the OSR (see the const block), then jump to the
	// program start so the SM begins at `offset`. Writing INSTR executes immediately even
	// while the SM is stopped.
	h.INSTR.Set(insMovOsrInvNul)
	h.INSTR.Set(insOutPindirs14)
	h.INSTR.Set(insOutNull18)
	h.INSTR.Set(uint32(offset)) // jmp offset

	sm.SetEnabled(true)
	return nil
}

// configureDMA points the data channel at the live buffer and the claimed SM's TX FIFO,
// enables its completion IRQ on DMA line 1, and triggers the first pass.
func configureDMA() {
	dmaCh.WRITE_ADDR.Set(ptr(unsafe.Pointer(pioSM.TxReg())))
	dmaCh.READ_ADDR.Set(bufBase[live])
	dmaCh.TRANS_COUNT.Set(streamWords)

	// TX DREQ for the claimed SM: 8 per PIO block, +1 per SM (PIO0 TX0=0, TX1=1, ...).
	dreq := uint32(pioSM.PIO().BlockIndex())*8 + uint32(pioSM.StateMachineIndex())

	// Word transfers, read increments through the stream, write stays on the FIFO, paced by
	// the PIO TX DREQ. CHAIN_TO must be this channel itself (a non-zero channel left at 0
	// would chain to CH0) — i.e. no chaining.
	dmaCtrl = uint32(rp.DMA_CH0_CTRL_TRIG_EN) |
		(rp.DMA_CH0_CTRL_TRIG_DATA_SIZE_SIZE_WORD << rp.DMA_CH0_CTRL_TRIG_DATA_SIZE_Pos) |
		uint32(rp.DMA_CH0_CTRL_TRIG_INCR_READ) |
		(uint32(dmaChan) << rp.DMA_CH0_CTRL_TRIG_CHAIN_TO_Pos) |
		(dreq << rp.DMA_CH0_CTRL_TRIG_TREQ_SEL_Pos)

	rp.DMA.INTE1.SetBits(1 << dmaChan) // completion IRQ on DMA line 1 (line 0 left for others)
	interrupt.New(rp.IRQ_DMA_IRQ_1, dmaISR).Enable()

	dmaCh.CTRL_TRIG.Set(dmaCtrl) // go
}

// dmaISR fires when the data channel finishes streaming one full frame. It adopts a pending buffer
// swap (the frame boundary), then re-arms the channel from the live buffer. This is the only
// CPU work during refresh — once per frame.
func dmaISR(interrupt.Interrupt) {
	rp.DMA.INTS1.Set(1 << dmaChan) // write-1-clear this channel's completion flag (line 1)

	if want != live {
		live = want
	}
	dmaCh.READ_ADDR.Set(bufBase[live])
	dmaCh.TRANS_COUNT.Set(streamWords)
	dmaCh.CTRL_TRIG.Set(dmaCtrl)
}

// ─── TUNING ─── pio's only timing knob. Change it here and re-flash; nothing in Config
// controls timing. (The pixel clock is beatDiv, in the PIO const block above.)
//
// holdDutyRatio sets the auto plane-0 dwell: the lit holds run ~holdDutyRatio× the blanked
// shift+latch time, i.e. duty ≈ ratio/(ratio+1). 9 ⇒ ~90%. Higher = brighter / lower refresh;
// lower = dimmer / faster. Because holds are count-encoded this costs no RAM at any value — it
// only trades brightness for refresh rate.
const holdDutyRatio = 1

// autoBaseHold returns the plane-0 dwell (PIO cycles) for holdDutyRatio: holds ≈ ratio× the
// blanked shift+latch time. plane k dwells the result <<k; BCM weighting is exact from plane 0,
// so gradients/darks stay clean at any depth.
func autoBaseHold(width, planes int) int {
	shiftLatchCycles := (2*width + 3) * shiftWordCycles
	return holdDutyRatio * shiftLatchCycles * planes / ((1 << uint(planes)) - 1)
}

// addrBits returns the row-select bits (A..E on GP6..GP10) for row pair r.
func addrBits(r int) uint32 {
	var a uint32
	if r&1 != 0 {
		a |= 1 << 6
	}
	if r&2 != 0 {
		a |= 1 << 7
	}
	if r&4 != 0 {
		a |= 1 << 8
	}
	if r&8 != 0 {
		a |= 1 << 9
	}
	if r&16 != 0 {
		a |= 1 << 10
	}
	return a
}
